def _make_datetime_field_compatible(self, field):
    """
    Creates a new datetime object to avoid issues occurring due to upgrading
    python-datetuil version from 2.4.0

    More info: https://openedx.atlassian.net/browse/BOM-2245
    """
    if isinstance(field, datetime):
        if isinstance(field.tzinfo, tzlocal) and not hasattr(field.tzinfo, '_hasdst'):

            logger.info('Python-dateutil logs: Making datetime field compatible to python-dateutil package')
            return datetime(
                year=field.year, month=field.month, day=field.day,
                hour=field.hour, minute=field.minute, second=field.second,
                tzinfo=tzlocal()
            )
    return field

def all_gather(self, tensor: torch.Tensor, mesh_dim: int = 0) -> torch.Tensor:
    dim_group = self._dim_groups[mesh_dim]
    # CommTensor does not change eager mode behavior. During tracing, it
    # makes sure communication result is properly waited before subsequent
    # read operations.
    return all_gather(CommTensor(tensor.contiguous()), group=dim_group)

def __update( self ) :

    if self.__frame == self.__context.getFrame() :
        return

    if self.__context.getFrame() not in self.__validFrames :
        raise ValueError( "Invalid frame" )

    self.clear()
    for plug in self.__variables.children() :
        value, name = self.__variables.memberDataAndName( plug )
        if value is None :
            continue
        with IECore.IgnoredExceptions( Exception ) :
            value = value.value
        if isinstance( value, str ) :

            value = self.__context.substitute( value )

        self[name] = value

    self.__frame = self.__context.getFrame()

